import{_ as n,C as o,o as d,c as i,j as r,a as t,E,a2 as c,b as l,w as a,a3 as A}from"./chunks/framework.BTSE7CIX.js";const y=JSON.parse('{"title":"04. 目录结构与路由取舍","description":"实测剖析静态网站生成器在目录深度、文件排序与 URL 纯净度、自动侧边栏维护上的不可能三角。","frontmatter":{"title":"04. 目录结构与路由取舍","description":"实测剖析静态网站生成器在目录深度、文件排序与 URL 纯净度、自动侧边栏维护上的不可能三角。","outline":[2,3]},"headers":[],"relativePath":"04-directory/index.md","filePath":"04-directory/index.md"}'),g={name:"04-directory/index.md"},m={id:"_04-目录结构与路由取舍",tabindex:"-1"};function u(D,e,f,p,x,h){const s=o("Badge"),B=o("Mermaid");return d(),i("div",null,[r("h1",m,[e[0]||(e[0]=t("04. 目录结构与路由取舍 ",-1)),E(s,{type:"warning",text:"没有银弹"}),e[1]||(e[1]=t()),e[2]||(e[2]=r("a",{class:"header-anchor",href:"#_04-目录结构与路由取舍","aria-label":'Permalink to "04. 目录结构与路由取舍 <Badge type="warning" text="没有银弹" />"'},"​",-1))]),e[4]||(e[4]=c('<p>静态网站生成器的目录组织看似简单，实则受制于一组<strong>不可能三角</strong>：<strong>本地编辑器/GitHub 浏览友好度</strong>、<strong>生成 URL 的纯净度</strong>、以及<strong>多级侧边栏的零配置自动化</strong>，没有任何一个现有方案能同时完美兼顾三者。</p><h2 id="_1-痛点一-文档根目录隔离-vs-目录层级深度" tabindex="-1">1. 痛点一：文档根目录隔离 vs 目录层级深度 <a class="header-anchor" href="#_1-痛点一-文档根目录隔离-vs-目录层级深度" aria-label="Permalink to &quot;1. 痛点一：文档根目录隔离 vs 目录层级深度&quot;">​</a></h2><p>在 <strong>VitePress v1</strong> 中，官方默认推荐直接以项目根目录（或单层 <code>docs/</code>）作为内容根：</p><ul><li><strong>优势</strong>：目录层级极浅，把一个现有的 Markdown 文件夹变成网站几乎零迁移成本。</li><li><strong>真实痛点</strong>：内容文件（<code>index.md</code>、<code>01-annotations.md</code>）与工程文件（<code>package.json</code>、<code>README.md</code>）混处同一目录。<strong>如果不显式配置 <code>srcExclude: [&#39;README.md&#39;]</code>，仓库本身的 <code>README.md</code> 会被 VitePress 当成网页编译为 <code>/README.html</code></strong>（甚至若缺少 <code>index.md</code> 会直接篡夺网站首页）。</li></ul><div class="warning custom-block"><p class="custom-block-title">对比 Astro Starlight 的另一极端</p><p>Astro 7 + Starlight 强制要求文档深埋在 <code>src/content/docs/</code>（前置 3 层目录）并配合 <code>src/content.config.ts</code>。虽然彻底根除了误编译 <code>README.md</code> 的隐患，但目录层级过深，对想直接挂载纯笔记库（如 Obsidian Vault）的用户侵入性很强。</p></div><h2 id="_2-痛点二-本地排序前缀-01-与干净-url-的两难" tabindex="-1">2. 痛点二：本地排序前缀（<code>01-</code>）与干净 URL 的两难 <a class="header-anchor" href="#_2-痛点二-本地排序前缀-01-与干净-url-的两难" aria-label="Permalink to &quot;2. 痛点二：本地排序前缀（`01-`）与干净 URL 的两难&quot;">​</a></h2><p>当一个目录下有多篇有先后阅读顺序的文档时：</p><table tabindex="0"><thead><tr><th style="text-align:left;">排序策略</th><th style="text-align:left;">在 IDE / GitHub 文件列表中的顺序</th><th style="text-align:left;">生成的线上 URL</th><th style="text-align:left;">核心代价</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>文件名加数字前缀</strong><br>（本子站做法：<code>01-prefix-order.md</code>）</td><td style="text-align:left;">按 <code>01</code>、<code>02</code> 整齐排列，一目了然</td><td style="text-align:left;"><code>/04-directory/nested/01-prefix-order</code>（<strong>URL 被序号污染</strong>，中间插入新文章改序号会导致旧链接全部 404）</td><td style="text-align:left;">若想抹除 URL 中的 <code>01-</code>，必须在 <code>.vitepress/config.mts</code> 额外维护 <code>rewrites</code> 映射规则</td></tr><tr><td style="text-align:left;"><strong>纯语义文件名 + Frontmatter <code>order</code></strong><br>（Starlight 子站做法：<code>zeta-first.md</code>）</td><td style="text-align:left;">按字母 <code>alpha</code> -&gt; <code>zeta</code> 排列（<strong>与实际阅读顺序颠倒</strong>，文章超 20 篇后本地极难找）</td><td style="text-align:left;"><code>/04-directory/nested/zeta-first</code>（URL 纯净稳定，调整顺序不破链接）</td><td style="text-align:left;">必须在打开每个文件看 Frontmatter 后才知道谁排第一</td></tr></tbody></table><h2 id="_3-痛点三-多级嵌套子目录与侧边栏四大流派对比" tabindex="-1">3. 痛点三：多级嵌套子目录与侧边栏四大流派对比 <a class="header-anchor" href="#_3-痛点三-多级嵌套子目录与侧边栏四大流派对比" aria-label="Permalink to &quot;3. 痛点三：多级嵌套子目录与侧边栏四大流派对比&quot;">​</a></h2><p>本章节专门建立了嵌套子目录 <code>04-directory/nested/</code> 以实测多级路由（可直接点击左侧边栏或下方链接进入子页面验证）：</p><ul><li><a href="./nested/01-prefix-order">进入嵌套子页 1：<code>04-directory/nested/01-prefix-order</code></a></li><li><a href="./nested/02-manual-sidebar">进入嵌套子页 2：<code>04-directory/nested/02-manual-sidebar</code></a></li></ul>',11)),(d(),l(A,null,{default:a(()=>[E(B,{id:"mermaid-101",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Root%5B%22%E5%A4%9A%E7%BA%A7%E7%9B%AE%E5%BD%95%E4%BE%A7%E8%BE%B9%E6%A0%8F%E7%BB%B4%E6%8A%A4%E7%9A%84%E5%9B%9B%E5%A4%A7%E6%B5%81%E6%B4%BE%22%5D%0A%20%20%20%20Root%20--%3E%20VP%5B%22VitePress%20v1%3A%20%E7%BA%AF%E9%85%8D%E7%BD%AE%E6%96%87%E4%BB%B6%E6%89%8B%E5%86%99%E6%B4%BE%22%5D%0A%20%20%20%20Root%20--%3E%20SL%5B%22Astro%20Starlight%3A%20%E6%96%87%E4%BB%B6%E5%A4%B9%20autogenerate%20%E6%B4%BE%22%5D%0A%20%20%20%20Root%20--%3E%20Docus%5B%22Docusaurus%3A%20%E7%9B%AE%E5%BD%95%E5%86%85%20_category_.json%20%E6%B4%BE%22%5D%0A%20%20%20%20Root%20--%3E%20Hugo%5B%22Hugo%3A%20_index.md%20Branch%20Bundle%20%E6%B4%BE%22%5D%0A%0A%20%20%20%20VP%20--%3E%20VP_C%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E6%96%B0%E5%A2%9E%E6%96%87%E4%BB%B6%E4%B8%8D%E6%94%B9%20config.mts%20%E5%B0%B1%E4%BC%9A%E6%B2%A6%E4%B8%BA%E6%97%A0%E5%85%A5%E5%8F%A3%E5%AD%A4%E5%B2%9B%E9%A1%B5%22%5D%0A%20%20%20%20SL%20--%3E%20SL_C%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E8%87%AA%E5%8A%A8%E6%89%AB%E6%8F%8F%E5%AD%90%E7%9B%AE%E5%BD%95%E6%97%B6%E5%88%86%E7%BB%84%E5%90%8D%E7%9B%B4%E6%8E%A5%E6%9A%B4%E9%9C%B2%E8%8B%B1%E6%96%87%E7%9B%AE%E5%BD%95%E5%90%8D%20nested%22%5D%0A%20%20%20%20Docus%20--%3E%20Do_C%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E7%BA%AF%E5%87%80%E7%9A%84%20Markdown%20%E6%96%87%E4%BB%B6%E5%A4%B9%E9%87%8C%E8%A2%AB%E8%BF%AB%E5%A1%9E%E6%BB%A1%E9%9B%B6%E6%95%A3%20JSON%20%E9%85%8D%E7%BD%AE%22%5D%0A%20%20%20%20Hugo%20--%3E%20Hu_C%5B%22%E4%BB%A3%E4%BB%B7%3A%20_index.md%20%E4%B8%8E%20index.md%20%E4%B8%80%E5%AD%97%E4%B9%8B%E5%B7%AE%E5%8D%B4%E6%94%B9%E5%8F%98%E6%95%B4%E4%B8%AA%E5%AD%90%E6%A0%91%E8%B7%AF%E7%94%B1%E8%AF%AD%E4%B9%89%22%5D%0A"})]),fallback:a(()=>[...e[3]||(e[3]=[t(" Loading... ",-1)])]),_:1}))])}const b=n(g,[["render",u]]);export{y as __pageData,b as default};
